<script setup>
import { computed } from 'vue'
import { CalendarDays, Check, CheckCircle2, Clock3, LoaderCircle, UserRound, XCircle } from 'lucide-vue-next'
const props = defineProps({ confirmation: { type: Object, required: true }, disabled: Boolean })
const emit = defineEmits(['confirm', 'cancel'])
const timezone = computed(() => props.confirmation.timezone || 'America/Sao_Paulo')
const format = value => value && !Number.isNaN(new Date(value).getTime()) ? new Intl.DateTimeFormat('pt-BR', { timeZone: timezone.value, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : ''
const successLabel = { create_appointment: 'Agendamento confirmado', reschedule_appointment: 'Atendimento remarcado', cancel_appointment: 'Atendimento cancelado' }
const title = computed(() => props.confirmation.title || ({ create_appointment: 'Novo agendamento', reschedule_appointment: 'Remarcar atendimento', cancel_appointment: 'Cancelar atendimento' }[props.confirmation.type]) || 'Confirmação de ação')
const status = computed(() => ({ pending: { label: 'Aguardando você', icon: Clock3 }, processing: { label: 'Em processamento', icon: LoaderCircle }, success: { label: 'Concluído', icon: CheckCircle2 }, failed: { label: 'Não concluído', icon: XCircle }, cancelled: { label: 'Cancelado', icon: XCircle } }[props.confirmation.status] || { label: 'Indisponível', icon: XCircle }))
const primaryLabel = computed(() => props.confirmation.primaryActionLabel || ({ create_appointment: 'Confirmar agendamento', reschedule_appointment: 'Confirmar remarcação', cancel_appointment: 'Confirmar cancelamento' }[props.confirmation.type]) || 'Confirmar ação')
</script>

<template>
  <section class="lia-action-card" :class="[confirmation.status, { destructive: confirmation.destructive }]" :aria-label="title">
    <header><span class="eyebrow">{{ title }}</span><span class="status-pill"><component :is="status.icon" :size="12" :class="{ spinning: confirmation.status === 'processing' }" />{{ status.label }}</span></header>
    <div v-if="['pending', 'processing', 'success'].includes(confirmation.status)" class="action-steps" aria-label="Etapas da ação"><span class="done"><i><Check :size="10" /></i> Preparado</span><b></b><span :class="{ done: confirmation.status !== 'pending' }"><i><Check v-if="confirmation.status !== 'pending'" :size="10" /><span v-else>2</span></i> Confirmação</span><b></b><span :class="{ done: confirmation.status === 'success' }"><i><Check v-if="confirmation.status === 'success'" :size="10" /><span v-else>3</span></i> Concluído</span></div>
    <p v-if="confirmation.status === 'pending'" class="instruction">Confira os detalhes antes de confirmar.</p>
    <p v-else-if="confirmation.status === 'success'" class="result" role="status">{{ successLabel[confirmation.type] || 'Ação confirmada' }}</p>
    <div v-if="confirmation.patientName" class="patient"><span><UserRound :size="16" /></span><strong>{{ confirmation.patientName }}</strong></div>
    <div v-if="confirmation.startAt" class="appointment-details"><CalendarDays :size="14" /><div><template v-if="confirmation.type === 'reschedule_appointment'"><span class="old-date">De: {{ format(confirmation.previousStartAt) }}</span><strong>Para: {{ format(confirmation.startAt) }}</strong></template><strong v-else>{{ format(confirmation.startAt) }}</strong><span v-if="confirmation.professionalName">{{ confirmation.professionalName }}</span><small>Fuso: {{ timezone }}</small></div></div>
    <div v-if="confirmation.status === 'pending'" class="actions"><button type="button" :disabled="disabled" :class="{ danger: confirmation.destructive || confirmation.type === 'cancel_appointment' }" @click="emit('confirm')">{{ primaryLabel }}</button><button type="button" :disabled="disabled" class="secondary" @click="emit('cancel')">{{ confirmation.type === 'cancel_appointment' ? 'Voltar' : 'Cancelar' }}</button></div>
    <template v-else-if="confirmation.status === 'processing'"><p class="state-note" role="status">Ação em processamento. Aguarde a atualização.</p><div v-if="confirmation.recoverable" class="actions"><button type="button" :disabled="disabled" @click="emit('confirm')">Verificar e recuperar ação</button></div></template>
    <template v-else-if="confirmation.status === 'failed'"><p class="state-note failed-note" role="alert">Não foi possível concluir a ação.</p><p class="state-note">{{ confirmation.errorMessage || 'Consulte novamente e solicite um novo card de confirmação.' }}</p></template>
    <p v-else-if="confirmation.status === 'cancelled'" class="state-note">Ação cancelada</p>
  </section>
</template>

<style scoped>
.lia-action-card { margin-top: 14px; padding: 17px; border: 1px solid var(--lia-line, #e4e8ef); border-radius: 18px; color: var(--lia-text, #243247); background: var(--lia-surface, #fff); box-shadow: 0 4px 18px #14233d04; }
header { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; }.eyebrow { font-size: 11px; font-weight: 600; }.status-pill { display: inline-flex; align-items: center; gap: 5px; padding: 5px 8px; border: 1px solid #dba53630; border-radius: 20px; color: #986b16; background: #dba5360c; font-size: 9px; white-space: nowrap; }.success .status-pill { color: #0a9b79; border-color: #12ba9135; background: #12ba910d; }.processing .status-pill { color: var(--lia-blue, #0057ff); border-color: #0057ff30; background: #0057ff0a; }.failed .status-pill { color: #c94360; border-color: #c9436030; background: #c943600c; }.cancelled .status-pill { color: var(--lia-muted, #758095); border-color: var(--lia-line, #e4e8ef); background: var(--lia-soft, #f4f5f8); }
.action-steps { display: flex; align-items: center; gap: 6px; margin: 19px 0; }.action-steps>span { display: flex; align-items: center; gap: 4px; font-size: 9px; color: var(--lia-muted, #758095); }.action-steps i { display: grid; place-items: center; width: 17px; height: 17px; border: 1px solid var(--lia-line, #e4e8ef); border-radius: 50%; font-style: normal; font-size: 9px; }.action-steps b { flex: 1; height: 1px; background: var(--lia-line, #e4e8ef); }.action-steps .done { color: var(--lia-blue, #0057ff); }.action-steps .done i { border-color: var(--lia-blue, #0057ff); color: #fff; background: var(--lia-blue, #0057ff); }.success .done { color: #0c9e7d; }.success .done i { background: #0c9e7d; border-color: #0c9e7d; }
.instruction,.state-note { margin: 12px 0 0; font-size: 11px; color: var(--lia-muted, #758095); line-height: 1.6; }.result { margin: 10px 0 0; color: #0c9e7d; font-size: 12px; font-weight: 550; }.patient { display: flex; align-items: center; gap: 8px; margin: 16px 0 10px; }.patient>span { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 10px; color: var(--lia-blue, #0057ff); background: var(--lia-tint, #edf3ff); }.patient strong { font-size: 13px; font-weight: 600; overflow-wrap: anywhere; }.appointment-details { display: flex; align-items: flex-start; gap: 8px; margin-left: 5px; color: var(--lia-muted, #758095); }.appointment-details>svg { margin-top: 2px; flex-shrink: 0; }.appointment-details>div { display: grid; gap: 4px; }.appointment-details strong { font-size: 11px; font-weight: 500; color: var(--lia-text, #243247); }.appointment-details span { font-size: 11px; }.appointment-details small { margin-top: 2px; font-size: 9px; }.appointment-details .old-date { text-decoration: line-through; opacity: .7; }.actions { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 17px; padding-top: 14px; border-top: 1px solid var(--lia-line, #e4e8ef); }.actions button { padding: 9px 12px; border: 1px solid var(--lia-blue, #0057ff); border-radius: 10px; background: var(--lia-blue, #0057ff); color: #fff; font: inherit; font-size: 11px; font-weight: 550; cursor: pointer; }.actions button.secondary { border-color: var(--lia-line, #e4e8ef); color: var(--lia-muted, #758095); background: var(--lia-surface, #fff); }.actions button.danger { background: #bf4058; border-color: #bf4058; }.actions button:disabled { opacity: .5; cursor: default; }.actions button:focus-visible { outline: 2px solid var(--lia-blue, #0057ff); outline-offset: 3px; }.failed-note { color: #c94360; }.spinning { animation: action-spin 1s linear infinite; }@keyframes action-spin { to { transform: rotate(360deg); } }@media(prefers-reduced-motion: reduce) { .spinning { animation: none; } }
</style>
